('QI_00102', 'QV_249', 0, 1, 3, 3, 4, '增设强电箱380V', 12, 3, '', 1080000, 1080000, 1080000, 0, 0),
('QI_00103', 'QV_249', 0, 1, 3, 3, 4, '独立车库电路敷设', 12, 3, '1.工艺：确定位置→开槽→布管穿线→线路检测。2.乙供：2.5平方BV线、辅料、人工及机械。3.说明：包含2个插座、1个照明回路（2个灯位）、卷帘门电源；不包含充电桩电源敷设。', 900000, 900000, 900000, 0, 0),
('QI_00104', 'QV_249', 0, 1, 3, 3, 4, '阳光房电路敷设', 12, 3, '1.工艺：确定位置→开槽→布管穿线→线路检测。2.乙供：2.5平方BV线、辅料、人工及机械。3.说明：包含2个插座、1个照明回路（2个灯位）、电动天窗电源。', 900000, 900000, 900000, 0, 0),
('QI_00105', 'QV_249', 0, 1, 3, 3, 15, '室外电源点位', 12, 3, '1.工艺：确定位置→布管穿线→线路检测。2.乙供：4平方BV线、辅料、人工及机械。3.说明：仅限于外墙墙面预留插座（4平方BV线）或照明（2.5平方BV线），单独回路控制；此项目仅限于单独插座或照明，如需插座和照明同时预留，则依次累计增加此项。', 400000, 400000, 400000, 0, 0),
('QI_00106', 'QV_249', 0, 1, 3, 1, 4, '全屋总控开关（平层）', 12, 3, '1.工艺：管内穿2.5平方BV线。2.乙供：子目中包含的材料、人工及机械。3.说明：不含所需要的接触器和组装配线。', 350000, 350000, 350000, 0, 0),
('QI_00107', 'QV_249', 0, 1, 3, 1, 4, '全屋总控开关（非平层）', 12, 3, '1.工艺：管内穿2.5平方BV线。2.乙供：子目中包含的材料、人工及机械。3.说明：不含所需要的接触器和组装配线；按层收取费用。', 550000, 550000, 550000, 0, 0),
('QI_00108', 'QV_249', 0, 1, 1, 1, 3, '卫生间地面回填层铲除', 2, 1, '1.工艺：人工保护性拆除卫生间地面/地热回填层并装袋。2.乙供：垃圾袋、人工及机械。3.说明：原始地热不更换情况下收取此项费用，并保留卫生间地热管；垃圾排放到园区指定地点，如需外运费用另计。', 70000, 70000, 70000, 0, 1),
('QI_00109', 'QV_249', 0, 1, 1, 1, 3, '下沉卫生间地面回填层铲除', 2, 1, '1.工艺：人工保护性拆除卫生间地面/地热回填层并装袋。2.乙供：垃圾袋、人工及机械。3.说明：卫生间地热管保留；垃圾排放到园区指定地点，如需外运费用另计。', 100000, 100000, 100000, 0, 1),
('QI_00110', 'QV_249', 0, 1, 1, 1, 3, '卫生间地面回填', 2, 4, '1.工艺：人工清理基层→地面预湿→水泥砂浆搅拌→地面找平→边角圆弧处理→门口拦水坝制作。2.乙供：沙子、水泥、人工及机械。3.说明： 卫生间必做项，不区分是否重新做地热。', 60000, 60000, 60000, 0, 1),
('QI_00111', 'QV_249', 0, 1, 1, 1, 3, '下沉卫生间地面回填', 2, 4, '1.工艺：沉箱内下水管道保护砌筑→回填陶粒或河石→钢筋绑扎→地面混凝土浇筑并回填→养护。2.乙供：沙子、水泥、陶粒/河石、钢筋、人工及机械。', 180000, 180000, 180000, 0, 1),
('QI_00112', 'QV_249', 0, 1, 4, 1, 3, '地面防水涂刷', 2, 4, '1.工艺：边角及排水管口加强层处理→坐便口高分子防水加强处理→防水材料搅拌→刚性防水材料涂刷一遍→柔性防水材料涂刷二遍→闭水试验。 2.乙供：水泥、沙子、刚性防水剂、柔性防水剂、高分子防水、人工及机械。3.说明：墙（含门洞口两侧）地面交接涂刷高度不得低于地面以上300mm。', 168000, 168000, 168000, 0, 1),
('QI_00113', 'QV_249', 0, 1, 1, 1, 3, '下沉卫生间地面防水涂刷', 2, 4, '1.工艺：沉箱防水底涂涂刷一遍→沉箱柔性防水材料涂刷二遍→闭水试验→边角及排水管口加强层处理→坐便口高分子防水加强处理→防水材料搅拌→刚性防水材料涂刷一遍→柔性防水材料涂刷二遍→闭水试验。 2.乙供：水泥、沙子、刚性防水剂、柔性防水剂、高分子防水、人工及机械。3.说明：墙（含门洞口两侧）地面交接涂刷高度不得低于地面以上300mm。', 288000, 288000, 288000, 0, 1),
('QI_00114', 'QV_249', 0, 1, 1, 1, 3, '嵌入式浴缸砌筑抹灰（方形）', 12, 4, '1.工艺：地面防水检查→放线定位→基层处理→水泥砂浆搅拌→墙体砌筑（预留检修口）→抹灰→养护。2.乙供：沙子、水泥、人工费及机械。3.说明：不包含浴缸安装费，浴缸下方需增加地漏，地漏甲供。', 980000, 980000, 980000, 0, 1),
('QI_00115', 'QV_249', 0, 1, 1, 1, 3, '嵌入式浴缸砌筑抹灰（异形）', 12, 4, '1.工艺：地面防水检查→放线定位→基层处理→水泥砂浆搅拌→墙体砌筑（预留检修口）→抹灰→养护。2.乙供：沙子、水泥、人工费及机械。3.说明：不包含浴缸安装费，浴缸下方需增加地漏，地漏甲供。', 1830000, 1830000, 1830000, 0, 1),
('QI_00116', 'QV_249', 0, 1, 1, 1, 3, '淋浴区基石安装', 12, 4, '1.工艺：确认基石规格→定位放线→基石试铺→涂抹粘结材料→安装调平基石→铺设周边地砖→清洁养护。2.乙供：人工及机械。3.甲供：成品浴屏基石。', 180000, 180000, 180000, 0, 1),
('QI_00117', 'QV_249', 0, 1, 1, 1, 3, '淋浴区地面瓷砖局部下沉', 12, 4, '1.工艺：淋浴区内定位找坡→淋浴区内瓷砖铺设→下沉区域侧砖45度倒角处理→粘贴养护。2.乙供：人工及机械。3.说明：淋浴区地面低于卫生间瓷砖地面10-30mm，无传统挡水条，视觉平整且排水高效。', 280000, 280000, 280000, 0, 1),
